### Alternative Solution
#### Code
```javascript
function findMatrixAlt(nums) {
    let matrix = [];
    let rowMap = new Map();

    nums.forEach(num => {
        if (!rowMap.has(num)) {
            matrix.push([num]);
            rowMap.set(num, matrix.length - 1);
        } else {
            let rowIndex = rowMap.get(num);
            if (!matrix[rowIndex + 1]) matrix[rowIndex + 1] = [];
